composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    environment:
      TZ: {{env.TZ}}
      MYSQL_HOST: "{{serviceName}}-mariadb"
      MYSQL_DATABASE: snipeit
      MYSQL_USER: snipeit
      APP_KEY: {{env.APP_KEY}}
      MYSQL_PASSWORD: {{env.MYSQL_PASSWORD}}
      APP_URL: {{env.APP_URL}}
    volumes:
      - {{appDataPath}}/data:/var/lib/snipeit
    depends_on:
      - {{serviceName}}-mariadb
  {{serviceName}}-mariadb:
    image: mariadb:11
    container_name: {{serviceName}}-mariadb
    restart: unless-stopped
    environment:
      MYSQL_DATABASE: snipeit
      MYSQL_USER: snipeit
      MYSQL_PASSWORD: {{env.MYSQL_PASSWORD}}
      MYSQL_ROOT_PASSWORD: {{env.MYSQL_PASSWORD}}
    volumes:
      - {{appDataPath}}/mariadb:/var/lib/mysql
